-- c012-v001: Tentang tetapi – karunia–rohani saudara-saudara tidak aku–ingin kamu tidak–tahu
-- c012-v002: Kamu–tahu bahwa ketika bangsa-bangsa kamu–adalah kepada – berhala-berhala – bisu bagaimanapun – kamu–dituntun disesatkan
-- c012-v003: Oleh–karena–itu aku–memberitahukan kepadamu bahwa tidak–seorangpun dalam Roh Allah berbicara berkata TERKUTUK YESUS dan tidak–seorangpun sanggup berkata TUHAN YESUS kecuali – dalam Roh Kudus
-- c012-v004: Bermacam-macam tetapi karunia ada – tetapi sama Roh
-- c012-v005: dan bermacam-macam pelayanan ada dan – sama Tuhan
-- c012-v006: dan bermacam-macam pekerjaan ada dan – tetapi sama Allah yang mengerjakan – semua dalam semua
-- c012-v007: Kepada–masing-masing tetapi diberikan – pernyataan – Roh untuk – keuntungan
-- c012-v008: Kepada–yang–satu memang karena melalui – Roh diberikan perkataan hikmat Kepada–yang–lain tetapi perkataan pengetahuan menurut – sama Roh
-- c012-v009: Kepada–yang–lain iman dalam – sama Roh Kepada–yang–lain tetapi karunia-karunia penyembuhan dalam – satu Roh
-- c012-v010: Kepada–yang–lain tetapi pekerjaan-pekerjaan kuasa Kepada–yang–lain tetapi nubuat Kepada–yang–lain tetapi pembedaan roh-roh Kepada–yang–lain berbagai–jenis bahasa–roh Kepada–yang–lain tetapi penafsiran bahasa–roh
-- c012-v011: Semua tetapi ini mengerjakan – satu dan – sama Roh membagikan secara–khusus kepada–masing-masing sebagaimana Ia–kehendaki
-- c012-v012: Sebab karena – tubuh satu adalah dan anggota banyak punya semua tetapi – anggota – tubuh banyak adalah satu adalah tubuh demikian juga – Kristus
-- c012-v013: Dan karena dalam satu Roh kita semua ke–dalam satu tubuh telah–dibaptis baik orang–Yahudi baik orang–Yunani baik hamba baik merdeka dan semua satu Roh telah–diberi–minum
-- c012-v014: Dan karena – tubuh bukan adalah satu anggota tetapi banyak
-- c012-v015: Jika berkata – kaki Karena bukan aku–adalah tangan bukan aku–adalah dari – tubuh Tidak karena ini bukan adalah dari – tubuh
-- c012-v016: Dan jika berkata – telinga Karena bukan aku–adalah mata bukan aku–adalah dari – tubuh Tidak karena ini bukan adalah dari – tubuh
-- c012-v017: Jika seluruh – tubuh mata di–mana – pendengaran? Jika seluruh pendengaran di–mana – penciuman?
-- c012-v018: Tetapi–sekarang tetapi – Allah menempatkan – anggota-anggota satu masing-masing dari–mereka dalam – tubuh sebagaimana Ia–kehendaki
-- c012-v019: Jika tetapi adalah – semua satu anggota di–mana – tubuh?
-- c012-v020: Sekarang tetapi banyak memang anggota satu tetapi tubuh
-- c012-v021: Tidak sanggup tetapi – mata berkata kepada– tangan Keperluan engkau tidak aku–punya atau lagi – kepala kepada– kaki-kaki Keperluan kamu tidak aku–punya
-- c012-v022: Tetapi lebih lagi – yang–tampaknya anggota – tubuh lebih–lemah adalah sangat–perlu adalah
-- c012-v023: dan yang kita–kira kurang–terhormat menjadi – tubuh kepada–ini hormat lebih–besar kita–kenakan dan – yang–tidak–sopan kita kesopanan lebih–besar punya
-- c012-v024: – tetapi yang–sopan kita tidak keperluan punya Tetapi – Allah mencampurkan – tubuh kepada–yang kurang lebih–besar memberi hormat
-- c012-v025: supaya jangan ada perpecahan dalam – tubuh tetapi – sama untuk satu–sama–lain mengkhawatirkan – anggota-anggota
-- c012-v026: Dan baik menderita satu anggota turut–menderita semua – anggota baik dimuliakan satu anggota turut–bersukacita semua – anggota
-- c012-v027: Kamu tetapi adalah tubuh Kristus dan anggota dari bagian
-- c012-v028: Dan yang memang menempatkan – Allah dalam – jemaat pertama rasul-rasul kedua nabi-nabi ketiga pengajar-pengajar lalu kuasa-kuasa lalu karunia-karunia penyembuhan pertolongan kepemimpinan berbagai–jenis bahasa–roh
-- c012-v029: Apakah semua rasul? Apakah semua nabi? Apakah semua pengajar? Apakah semua kuasa-kuasa?
-- c012-v030: Apakah semua karunia-karunia punya penyembuhan? Apakah semua dalam–bahasa–roh berbicara? Apakah semua menafsirkan?
-- c012-v031: Berusahalah–memperoleh tetapi – karunia-karunia – yang–lebih–besar Dan lagi yang–sangat mulia jalan kepadamu aku–tunjukkan

